// 角色的自动分配：部门发生变化才处理
if (!Objects.equals(beforeVo.getDepartmentId(), afterVo.getDepartmentId())) {
    transactionTemplate.execute(new TransactionCallbackWithoutResult() {
        @Override
        protected void doInTransactionWithoutResult(TransactionStatus status) {
            // 1.取消旧部门角色关联
            departmentRoleService.cancelRelateEmployeeDepartmentAndBusinessLineRole(beforeVo);
            // 2.取消旧部门下角色
            departmentRoleService.cancelRoleBelongDepartment(beforeVo.getDepartmentId(), beforeVo.getEmployeeNumber());
            // 3.关联新部门角色
            departmentRoleService.relateEmployeeDepartmentAndBusinessLineRole(afterVo);
        }
    });
}

// 注意：以下远程调用都在事务外 ——
tableAuManageService.handleEmployeeChangeAssign(afterVo);              // Tableau 报表权限（RPC）
remoteChidoriService.refreshAuth(Collections.singletonList(workNumber)); // 刷新 Chidori 会话（RPC）
